"""dialogues between the new characters (271 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'dialogue', 'text': "Barnabé, dans mon palais, j'ai cent domestiques.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0211_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0211', 'turn': 1, 'speaker': 'A', 'context': 'servants'},
    {'cat': 'dialogue', 'text': 'Et aucun ne sait plier une serviette en cygne, je suppose, Votre Altesse.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0211_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0211', 'turn': 2, 'speaker': 'B', 'context': 'servants'},
    {'cat': 'dialogue', 'text': 'Hé, Barnabé, tu me sers un bourbon, mon pote ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0212_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0212', 'turn': 1, 'speaker': 'A', 'context': 'bourbon'},
    {'cat': 'dialogue', 'text': 'Je ne suis pas votre pote, monsieur. Mais voici votre bourbon.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0212_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0212', 'turn': 2, 'speaker': 'B', 'context': 'bourbon'},
    {'cat': 'dialogue', 'text': 'Barnabé, avez-vous vu mes lunettes ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0213_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0213', 'turn': 1, 'speaker': 'A', 'context': 'glasses'},
    {'cat': 'dialogue', 'text': 'Sur votre front, monsieur le professeur. Comme les trois dernières fois.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0213_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0213', 'turn': 2, 'speaker': 'B', 'context': 'glasses'},
    {'cat': 'dialogue', 'text': 'Lucien. Vos bottes. Le tapis.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0214_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0214', 'turn': 1, 'speaker': 'A', 'context': 'mud'},
    {'cat': 'dialogue', 'text': 'Oh, pardon, monsieur Barnabé ! Je les enlève tout de suite !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0214_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0214', 'turn': 2, 'speaker': 'B', 'context': 'mud'},
    {'cat': 'dialogue', 'text': 'Pas les bottes. La boue.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0214_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0214', 'turn': 3, 'speaker': 'A', 'context': 'mud'},
    {'cat': 'dialogue', 'text': 'Toi, le majordome. Il y a un coffre-fort, dans cette maison ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0215_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0215', 'turn': 1, 'speaker': 'A', 'context': 'safe'},
    {'cat': 'dialogue', 'text': "Nous n'avons pas de coffre, monsieur. Et s'il y en avait un, je serais assis dessus.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0215_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0215', 'turn': 2, 'speaker': 'B', 'context': 'safe'},
    {'cat': 'dialogue', 'text': 'Barnabé ! Combien pour le manoir ? Je paie comptant !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0216_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0216', 'turn': 1, 'speaker': 'A', 'context': 'buy manor'},
    {'cat': 'dialogue', 'text': "Le manoir n'est pas à vendre, monsieur Callahan. Moi non plus.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0216_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0216', 'turn': 2, 'speaker': 'B', 'context': 'buy manor'},
    {'cat': 'dialogue', 'text': 'Belle maison, bien tenue. Vous auriez fait un bon second, Barnabé.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0217_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0217', 'turn': 1, 'speaker': 'A', 'context': 'first mate'},
    {'cat': 'dialogue', 'text': 'Merci, capitaine. Ici aussi, nous avons des tempêtes. On les appelle les invités.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0217_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0217', 'turn': 2, 'speaker': 'B', 'context': 'first mate'},
    {'cat': 'dialogue', 'text': 'Barnabé, mon châle. Et un porto. Et du silence.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0218_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0218', 'turn': 1, 'speaker': 'A', 'context': 'shawl'},
    {'cat': 'dialogue', 'text': 'Tout de suite, madame la duchesse. Surtout le silence.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0218_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0218', 'turn': 2, 'speaker': 'B', 'context': 'shawl'},
    {'cat': 'dialogue', 'text': 'Oh, darling ! Vous êtes le majordome ? Comme au cinéma !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0219_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0219', 'turn': 1, 'speaker': 'A', 'context': 'butler did it'},
    {'cat': 'dialogue', 'text': "Au cinéma, mademoiselle, c'est toujours le majordome le coupable.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0219_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0219', 'turn': 2, 'speaker': 'B', 'context': 'butler did it'},
    {'cat': 'dialogue', 'text': "Oh ! Et c'est vous ?", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0219_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0219', 'turn': 3, 'speaker': 'A', 'context': 'butler did it'},
    {'cat': 'dialogue', 'text': "Je n'ai pas encore décidé.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0219_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0219', 'turn': 4, 'speaker': 'B', 'context': 'butler did it'},
    {'cat': 'dialogue', 'text': 'Barnabé, vous servirez le thé dans la bibliothèque. Pour deux.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0220_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0220', 'turn': 1, 'speaker': 'A', 'context': 'tea for two'},
    {'cat': 'dialogue', 'text': 'Très bien, madame. Dois-je prévenir le médecin, par précaution ?', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0220_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0220', 'turn': 2, 'speaker': 'B', 'context': 'tea for two'},
    {'cat': 'dialogue', 'text': 'Monsieur Barnabé, vous savez pas la meilleure ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0221_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0221', 'turn': 1, 'speaker': 'A', 'context': 'the best one'},
    {'cat': 'dialogue', 'text': 'Je sais toujours la meilleure, Rosalie. Et je ne la répète jamais.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0221_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0221', 'turn': 2, 'speaker': 'B', 'context': 'the best one'},
    {'cat': 'dialogue', 'text': 'Oh, vous êtes pas drôle !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0221_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0221', 'turn': 3, 'speaker': 'A', 'context': 'the best one'},
    {'cat': 'dialogue', 'text': 'Mmm, Barnabé, tu souris jamais, honey ?', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0222_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0222', 'turn': 1, 'speaker': 'A', 'context': 'smile 1911'},
    {'cat': 'dialogue', 'text': 'Une fois, madame. En mil neuf cent onze. Je ne recommencerai pas.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0222_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0222', 'turn': 2, 'speaker': 'B', 'context': 'smile 1911'},
    {'cat': 'dialogue', 'text': 'Barnabé, une petite interview ? Depuis combien de temps servez-vous Ashcombe ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0223_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0223', 'turn': 1, 'speaker': 'A', 'context': 'interview'},
    {'cat': 'dialogue', 'text': 'Depuis trop longtemps pour parler, mademoiselle.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0223_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0223', 'turn': 2, 'speaker': 'B', 'context': 'interview'},
    {'cat': 'dialogue', 'text': 'Votre maison est très bien tenue, monsieur Barnabé.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0224_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0224', 'turn': 1, 'speaker': 'A', 'context': 'well kept'},
    {'cat': 'dialogue', 'text': 'Merci, mademoiselle. Vous êtes la première à le remarquer depuis dix ans.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0224_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0224', 'turn': 2, 'speaker': 'B', 'context': 'well kept'},
    {'cat': 'dialogue', 'text': "Hé, prince ! Tu veux jouer des tablas avec l'orchestre ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0225_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0225', 'turn': 1, 'speaker': 'A', 'context': 'tablas'},
    {'cat': 'dialogue', 'text': 'Volontiers. Mais je ne joue que si la musique est royale.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0225_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0225', 'turn': 2, 'speaker': 'B', 'context': 'tablas'},
    {'cat': 'dialogue', 'text': 'Ce soir, mon pote, elle est impériale.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0225_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0225', 'turn': 3, 'speaker': 'A', 'context': 'tablas'},
    {'cat': 'dialogue', 'text': 'Prince, vos ancêtres ont-ils connu les pharaons ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0226_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0226', 'turn': 1, 'speaker': 'A', 'context': 'temples'},
    {'cat': 'dialogue', 'text': 'Nos ancêtres étaient trop occupés à bâtir des temples plus grands, professeur.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0226_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0226', 'turn': 2, 'speaker': 'B', 'context': 'temples'},
    {'cat': 'dialogue', 'text': 'Lucien, vous conduisez bien ?', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0227_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0227', 'turn': 1, 'speaker': 'A', 'context': 'elephants'},
    {'cat': 'dialogue', 'text': "Oui, Votre Altesse. Sauf les éléphants. J'ai jamais essayé.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0227_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0227', 'turn': 2, 'speaker': 'B', 'context': 'elephants'},
    {'cat': 'dialogue', 'text': 'Prince, tes émeraudes, elles sont assurées ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0228_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0228', 'turn': 1, 'speaker': 'A', 'context': 'insured'},
    {'cat': 'dialogue', 'text': 'Par trois cents gardes, monsieur. Et par ma patience, qui a ses limites.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0228_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0228', 'turn': 2, 'speaker': 'B', 'context': 'insured'},
    {'cat': 'dialogue', 'text': "Prince ! Au Texas, j'ai plus de pétrole que vous n'avez de rubis !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0229_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0229', 'turn': 1, 'speaker': 'A', 'context': 'rubies'},
    {'cat': 'dialogue', 'text': "Peut-être. Mais mes rubis ne sentent pas l'essence.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0229_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0229', 'turn': 2, 'speaker': 'B', 'context': 'rubies'},
    {'cat': 'dialogue', 'text': 'Prince, je vous ai ramené de Bombay, en vingt-sept.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0230_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0230', 'turn': 1, 'speaker': 'A', 'context': 'bombay'},
    {'cat': 'dialogue', 'text': 'Je me souviens, capitaine. Votre cuisinier ne savait pas faire le curry.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0230_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0230', 'turn': 2, 'speaker': 'B', 'context': 'bombay'},
    {'cat': 'dialogue', 'text': "Il s'en souvient aussi. Vous l'avez fait débarquer à Suez.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0230_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0230', 'turn': 3, 'speaker': 'A', 'context': 'bombay'},
    {'cat': 'dialogue', 'text': 'Prince, enfin un homme bien élevé dans ce salon.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0231_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0231', 'turn': 1, 'speaker': 'A', 'context': 'manners'},
    {'cat': 'dialogue', 'text': 'Duchesse, vous me flattez. Et vous avez raison.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0231_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0231', 'turn': 2, 'speaker': 'B', 'context': 'manners'},
    {'cat': 'dialogue', 'text': 'Oh, darling ! Un vrai prince ! Vous avez des éléphants ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0232_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0232', 'turn': 1, 'speaker': 'A', 'context': 'one heart'},
    {'cat': 'dialogue', 'text': 'Quarante, mademoiselle. Et un seul cœur. Disponible.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0232_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0232', 'turn': 2, 'speaker': 'B', 'context': 'one heart'},
    {'cat': 'dialogue', 'text': 'Oh, my God !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0232_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0232', 'turn': 3, 'speaker': 'A', 'context': 'one heart'},
    {'cat': 'dialogue', 'text': 'Madame, vous portez le deuil avec une rare élégance.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0233_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0233', 'turn': 1, 'speaker': 'A', 'context': 'mourning'},
    {'cat': 'dialogue', 'text': "Merci, prince. J'ai beaucoup d'entraînement.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0233_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0233', 'turn': 2, 'speaker': 'B', 'context': 'mourning'},
    {'cat': 'dialogue', 'text': 'Pardon, Votre Altesse ! Je vous ai renversé du thé ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0234_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0234', 'turn': 1, 'speaker': 'A', 'context': 'tea drop'},
    {'cat': 'dialogue', 'text': "Une goutte. Elle a eu l'honneur de toucher un prince.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0234_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0234', 'turn': 2, 'speaker': 'B', 'context': 'tea drop'},
    {'cat': 'dialogue', 'text': 'Mmm, prince, tu as une voix à chanter le blues.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0235_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0235', 'turn': 1, 'speaker': 'A', 'context': 'princes blues'},
    {'cat': 'dialogue', 'text': "Le blues des princes, madame, c'est de tout avoir et de s'ennuyer quand même.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0235_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0235', 'turn': 2, 'speaker': 'B', 'context': 'princes blues'},
    {'cat': 'dialogue', 'text': 'Prince, quelle est la vraie raison de votre visite en France ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0236_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0236', 'turn': 1, 'speaker': 'A', 'context': 'real reason'},
    {'cat': 'dialogue', 'text': 'Le champagne, mademoiselle. Et les journalistes curieuses.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0236_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0236', 'turn': 2, 'speaker': 'B', 'context': 'real reason'},
    {'cat': 'dialogue', 'text': 'Prince Rajan, on dit que vous parlez neuf langues.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0237_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0237', 'turn': 1, 'speaker': 'A', 'context': 'ten languages'},
    {'cat': 'dialogue', 'text': 'Dix, mademoiselle Mei. La dixième est celle des silences, et vous la parlez mieux que moi.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0237_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0237', 'turn': 2, 'speaker': 'B', 'context': 'ten languages'},
    {'cat': 'dialogue', 'text': 'Monsieur Sonny, saviez-vous que les Égyptiens jouaient de la trompette ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0238_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0238', 'turn': 1, 'speaker': 'A', 'context': 'trumpets'},
    {'cat': 'dialogue', 'text': 'Sans blague, professeur ? Et ils swinguaient ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0238_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0238', 'turn': 2, 'speaker': 'B', 'context': 'trumpets'},
    {'cat': 'dialogue', 'text': "Ils réveillaient les morts. C'était le but.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0238_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0238', 'turn': 3, 'speaker': 'A', 'context': 'trumpets'},
    {'cat': 'dialogue', 'text': "Hé, petit, tu sais conduire un camion d'instruments ?", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0239_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0239', 'turn': 1, 'speaker': 'A', 'context': 'piano truck'},
    {'cat': 'dialogue', 'text': 'Oui, monsieur ! Enfin, avec un piano dedans, je sais pas.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0239_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0239', 'turn': 2, 'speaker': 'B', 'context': 'piano truck'},
    {'cat': 'dialogue', 'text': 'Sonny. À Chicago, tu jouais dans mon club.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0240_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0240', 'turn': 1, 'speaker': 'A', 'context': 'chicago club'},
    {'cat': 'dialogue', 'text': 'Et tu me payais jamais, Tony.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0240_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0240', 'turn': 2, 'speaker': 'B', 'context': 'chicago club'},
    {'cat': 'dialogue', 'text': "Je te laissais repartir avec tes doigts. C'est un salaire.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0240_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0240', 'turn': 3, 'speaker': 'A', 'context': 'chicago club'},
    {'cat': 'dialogue', 'text': 'Hé, le musicien ! Vous savez jouer de la country ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0241_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0241', 'turn': 1, 'speaker': 'A', 'context': 'country'},
    {'cat': 'dialogue', 'text': 'Pour toi, cow-boy, je joue du jazz avec un banjo dans le cœur.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0241_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0241', 'turn': 2, 'speaker': 'B', 'context': 'country'},
    {'cat': 'dialogue', 'text': 'Votre orchestre a joué sur mon paquebot, en vingt-neuf.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0242_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0242', 'turn': 1, 'speaker': 'A', 'context': 'ship band'},
    {'cat': 'dialogue', 'text': 'Ah ouais ! Le bateau qui tanguait en rythme !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0242_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0242', 'turn': 2, 'speaker': 'B', 'context': 'ship band'},
    {'cat': 'dialogue', 'text': "Ils tanguent tous, monsieur Sonny. C'est vous qui ne teniez plus debout.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0242_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0242', 'turn': 3, 'speaker': 'A', 'context': 'ship band'},
    {'cat': 'dialogue', 'text': 'Jeune homme, votre musique est une insulte à mes oreilles.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0243_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0243', 'turn': 1, 'speaker': 'A', 'context': 'insult'},
    {'cat': 'dialogue', 'text': 'Merci, duchesse ! Je vous joue la suite ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0243_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0243', 'turn': 2, 'speaker': 'B', 'context': 'insult'},
    {'cat': 'dialogue', 'text': 'Oh, Sonny darling, jouez mon thème ! Celui de mon film !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0244_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0244', 'turn': 1, 'speaker': 'A', 'context': 'theme'},
    {'cat': 'dialogue', 'text': 'Lequel, ma belle ? Celui où tu parles, ou celui où tu cries ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0244_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0244', 'turn': 2, 'speaker': 'B', 'context': 'theme'},
    {'cat': 'dialogue', 'text': 'Madame, un petit air gai pour vous ?', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0245_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0245', 'turn': 1, 'speaker': 'A', 'context': 'funeral swing'},
    {'cat': 'dialogue', 'text': 'Jouez plutôt une marche funèbre. Mais en swing.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0245_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0245', 'turn': 2, 'speaker': 'B', 'context': 'funeral swing'},
    {'cat': 'dialogue', 'text': "Monsieur Sonny, vous m'apprenez le charleston ?", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0246_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0246', 'turn': 1, 'speaker': 'A', 'context': 'charleston'},
    {'cat': 'dialogue', 'text': 'Viens là, ma belle ! Un, deux, et tu lances les genoux !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0246_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0246', 'turn': 2, 'speaker': 'B', 'context': 'charleston'},
    {'cat': 'dialogue', 'text': 'Sonny, tu joues trop vite, honey. Laisse respirer la chanson.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0247_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0247', 'turn': 1, 'speaker': 'A', 'context': 'too fast'},
    {'cat': 'dialogue', 'text': "Pour toi, Lou, je joue aussi lentement qu'un dimanche.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0247_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0247', 'turn': 2, 'speaker': 'B', 'context': 'too fast'},
    {'cat': 'dialogue', 'text': "Sonny, c'est vrai que votre trompettiste est recherché par la police ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0248_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0248', 'turn': 1, 'speaker': 'A', 'context': 'trumpeter'},
    {'cat': 'dialogue', 'text': 'Par la police, non. Par trois anciennes femmes, oui.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0248_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0248', 'turn': 2, 'speaker': 'B', 'context': 'trumpeter'},
    {'cat': 'dialogue', 'text': "À Shanghai, nous avons d'excellents orchestres de jazz.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0249_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0249', 'turn': 1, 'speaker': 'A', 'context': 'shanghai jazz'},
    {'cat': 'dialogue', 'text': "Je sais, ma belle. Mon batteur s'est marié là-bas. Deux fois.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0249_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0249', 'turn': 2, 'speaker': 'B', 'context': 'shanghai jazz'},
    {'cat': 'dialogue', 'text': 'Jeune homme, savez-vous réparer un phonographe de mil huit cent quatre-vingt-dix ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0250_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0250', 'turn': 1, 'speaker': 'A', 'context': 'phonograph'},
    {'cat': 'dialogue', 'text': 'Je peux essayer, professeur. Ça a un moteur ?', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0250_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0250', 'turn': 2, 'speaker': 'B', 'context': 'phonograph'},
    {'cat': 'dialogue', 'text': 'Une manivelle.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0250_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0250', 'turn': 3, 'speaker': 'A', 'context': 'phonograph'},
    {'cat': 'dialogue', 'text': 'Alors je suis votre homme.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0250_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0250', 'turn': 4, 'speaker': 'B', 'context': 'phonograph'},
    {'cat': 'dialogue', 'text': 'Professeur, ces vieilleries égyptiennes, ça vaut combien ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0251_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0251', 'turn': 1, 'speaker': 'A', 'context': 'price of mummies'},
    {'cat': 'dialogue', 'text': "Elles n'ont pas de prix, monsieur.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0251_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0251', 'turn': 2, 'speaker': 'B', 'context': 'price of mummies'},
    {'cat': 'dialogue', 'text': 'Tout a un prix, professeur. Même les momies.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0251_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0251', 'turn': 3, 'speaker': 'A', 'context': 'price of mummies'},
    {'cat': 'dialogue', 'text': 'Professeur ! Au Texas, on a des dinosaures !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0252_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0252', 'turn': 1, 'speaker': 'A', 'context': 'dinosaurs'},
    {'cat': 'dialogue', 'text': 'Fascinant ! Vivants ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0252_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0252', 'turn': 2, 'speaker': 'B', 'context': 'dinosaurs'},
    {'cat': 'dialogue', 'text': 'Ha ! Seulement mon beau-père.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0252_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0252', 'turn': 3, 'speaker': 'A', 'context': 'dinosaurs'},
    {'cat': 'dialogue', 'text': 'Capitaine, avez-vous déjà croisé une épave antique ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0253_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0253', 'turn': 1, 'speaker': 'A', 'context': 'wrecks'},
    {'cat': 'dialogue', 'text': 'Plusieurs, professeur. Et quelques passagers presque aussi anciens.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0253_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0253', 'turn': 2, 'speaker': 'B', 'context': 'wrecks'},
    {'cat': 'dialogue', 'text': 'Professeur, vous avez de la poussière jusque dans les sourcils.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0254_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0254', 'turn': 1, 'speaker': 'A', 'context': 'dust'},
    {'cat': 'dialogue', 'text': "C'est de la poussière de pharaon, duchesse ! Trois mille ans !", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0254_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0254', 'turn': 2, 'speaker': 'B', 'context': 'dust'},
    {'cat': 'dialogue', 'text': 'Ça ne la rend pas plus propre.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0254_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0254', 'turn': 3, 'speaker': 'A', 'context': 'dust'},
    {'cat': 'dialogue', 'text': 'Professeur, vous croyez aux malédictions ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0255_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0255', 'turn': 1, 'speaker': 'A', 'context': 'curses'},
    {'cat': 'dialogue', 'text': 'Scientifiquement, non. Personnellement, je ne touche plus aux sarcophages le vendredi.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0255_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0255', 'turn': 2, 'speaker': 'B', 'context': 'curses'},
    {'cat': 'dialogue', 'text': 'Professeur, combien de temps faut-il pour faire une momie ?', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0256_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0256', 'turn': 1, 'speaker': 'A', 'context': 'seventy days'},
    {'cat': 'dialogue', 'text': 'Soixante-dix jours, madame. Pourquoi cette question ?', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0256_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0256', 'turn': 2, 'speaker': 'B', 'context': 'seventy days'},
    {'cat': 'dialogue', 'text': 'Simple curiosité.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0256_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0256', 'turn': 3, 'speaker': 'A', 'context': 'seventy days'},
    {'cat': 'dialogue', 'text': "Professeur, j'ai rangé vos cailloux dans le tiroir.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0257_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0257', 'turn': 1, 'speaker': 'A', 'context': 'scarabs'},
    {'cat': 'dialogue', 'text': 'Mes cailloux ? Ce sont des scarabées sacrés, mon enfant !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0257_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0257', 'turn': 2, 'speaker': 'B', 'context': 'scarabs'},
    {'cat': 'dialogue', 'text': 'Oh ! Je les ai lavés, aussi.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0257_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0257', 'turn': 3, 'speaker': 'A', 'context': 'scarabs'},
    {'cat': 'dialogue', 'text': 'Professeur, chante-moi une chanson de tes pharaons.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0258_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0258', 'turn': 1, 'speaker': 'A', 'context': 'pharaoh songs'},
    {'cat': 'dialogue', 'text': "Hélas, madame, on n'a retrouvé que les paroles. Elles parlent surtout d'impôts.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0258_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0258', 'turn': 2, 'speaker': 'B', 'context': 'pharaoh songs'},
    {'cat': 'dialogue', 'text': "Professeur, ce sarcophage au grenier, c'est vous qui l'avez apporté ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0259_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0259', 'turn': 1, 'speaker': 'A', 'context': 'attic sarcophagus'},
    {'cat': 'dialogue', 'text': "Un sarcophage ? Au grenier ? Oh, mon Dieu, je l'avais oublié !", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0259_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0259', 'turn': 2, 'speaker': 'B', 'context': 'attic sarcophagus'},
    {'cat': 'dialogue', 'text': 'Professeur, la Chine aussi a ses tombeaux anciens.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0260_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0260', 'turn': 1, 'speaker': 'A', 'context': 'terracotta'},
    {'cat': 'dialogue', 'text': 'Je rêve de les voir, mademoiselle ! Les soldats de terre, les dragons...', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0260_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0260', 'turn': 2, 'speaker': 'B', 'context': 'terracotta'},
    {'cat': 'dialogue', 'text': 'Commencez par apprendre à boire le thé sans renverser. Le reste suivra.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0260_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0260', 'turn': 3, 'speaker': 'A', 'context': 'terracotta'},
    {'cat': 'dialogue', 'text': 'Toi, le chauffeur. Tu conduis vite ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0261_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0261', 'turn': 1, 'speaker': 'A', 'context': 'fast driver'},
    {'cat': 'dialogue', 'text': 'Euh... pas trop, monsieur.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0261_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0261', 'turn': 2, 'speaker': 'B', 'context': 'fast driver'},
    {'cat': 'dialogue', 'text': "Dommage. J'aurais eu du travail pour toi.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0261_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0261', 'turn': 3, 'speaker': 'A', 'context': 'fast driver'},
    {'cat': 'dialogue', 'text': 'Petit ! Tu sais conduire une Cadillac ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0262_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0262', 'turn': 1, 'speaker': 'A', 'context': 'cadillac'},
    {'cat': 'dialogue', 'text': "Une Cadillac ? Oh, monsieur, j'en rêve la nuit !", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0262_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0262', 'turn': 2, 'speaker': 'B', 'context': 'cadillac'},
    {'cat': 'dialogue', 'text': "Ha ! Je t'en offre une ! Enfin, peut-être.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0262_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0262', 'turn': 3, 'speaker': 'A', 'context': 'cadillac'},
    {'cat': 'dialogue', 'text': 'Mon garçon, vous avez le pied marin ?', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0263_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0263', 'turn': 1, 'speaker': 'A', 'context': 'sea legs'},
    {'cat': 'dialogue', 'text': "J'ai été malade trois fois sur le bateau, capitaine.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0263_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0263', 'turn': 2, 'speaker': 'B', 'context': 'sea legs'},
    {'cat': 'dialogue', 'text': "Alors vous avez le pied terrien. C'est très bien aussi.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0263_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0263', 'turn': 3, 'speaker': 'A', 'context': 'sea legs'},
    {'cat': 'dialogue', 'text': 'Chauffeur ! Ma voiture, immédiatement.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0264_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0264', 'turn': 1, 'speaker': 'A', 'context': 'my car'},
    {'cat': 'dialogue', 'text': 'Madame la duchesse, on est sur une île. Votre voiture est à Paris.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0264_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0264', 'turn': 2, 'speaker': 'B', 'context': 'my car'},
    {'cat': 'dialogue', 'text': 'Eh bien, faites-la venir !', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0264_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0264', 'turn': 3, 'speaker': 'A', 'context': 'my car'},
    {'cat': 'dialogue', 'text': "Oh, Lucien darling ! Vous m'emmènerez à Hollywood ?", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0265_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0265', 'turn': 1, 'speaker': 'A', 'context': 'hollywood drive'},
    {'cat': 'dialogue', 'text': "En voiture ? C'est loin, mademoiselle. Et il y a la mer.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0265_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0265', 'turn': 2, 'speaker': 'B', 'context': 'hollywood drive'},
    {'cat': 'dialogue', 'text': 'Lucien, vous vérifierez les freins de ma voiture, demain.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0266_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0266', 'turn': 1, 'speaker': 'A', 'context': 'brakes'},
    {'cat': 'dialogue', 'text': 'Ils sont en bon état, madame.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0266_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0266', 'turn': 2, 'speaker': 'B', 'context': 'brakes'},
    {'cat': 'dialogue', 'text': "C'est bien ce que je voulais savoir.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0266_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0266', 'turn': 3, 'speaker': 'A', 'context': 'brakes'},
    {'cat': 'dialogue', 'text': "Lucien ! T'as encore mis du cambouis sur mon tablier !", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0267_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0267', 'turn': 1, 'speaker': 'A', 'context': 'apron'},
    {'cat': 'dialogue', 'text': 'Pardon, Rosalie ! Je te le laverai !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0267_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0267', 'turn': 2, 'speaker': 'B', 'context': 'apron'},
    {'cat': 'dialogue', 'text': "Toi, laver ? T'arrives même pas à laver ta casquette !", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0267_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0267', 'turn': 3, 'speaker': 'A', 'context': 'apron'},
    {'cat': 'dialogue', 'text': "Mon petit, tu as l'air perdu. Viens près de Lou.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0268_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0268', 'turn': 1, 'speaker': 'A', 'context': 'lost boy'},
    {'cat': 'dialogue', 'text': "Merci, madame. C'est que je connais personne, ici.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0268_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0268', 'turn': 2, 'speaker': 'B', 'context': 'lost boy'},
    {'cat': 'dialogue', 'text': 'Lucien, vous avez conduit Ashcombe chez le notaire, la semaine dernière ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0269_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0269', 'turn': 1, 'speaker': 'A', 'context': 'notary'},
    {'cat': 'dialogue', 'text': 'Euh... je peux pas le dire, mademoiselle.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0269_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0269', 'turn': 2, 'speaker': 'B', 'context': 'notary'},
    {'cat': 'dialogue', 'text': 'Vous venez de le dire.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0269_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0269', 'turn': 3, 'speaker': 'A', 'context': 'notary'},
    {'cat': 'dialogue', 'text': 'Vous semblez inquiet, Lucien.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0270_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0270', 'turn': 1, 'speaker': 'A', 'context': 'crystal'},
    {'cat': 'dialogue', 'text': "C'est que j'ai cassé un verre, mademoiselle. En cristal.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0270_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0270', 'turn': 2, 'speaker': 'B', 'context': 'crystal'},
    {'cat': 'dialogue', 'text': "Personne n'a rien vu. Moi non plus.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0270_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0270', 'turn': 3, 'speaker': 'A', 'context': 'crystal'},
    {'cat': 'dialogue', 'text': 'Hé, Tony ! Tu veux investir dans le pétrole ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0271_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0271', 'turn': 1, 'speaker': 'A', 'context': 'oil investment'},
    {'cat': 'dialogue', 'text': "Moi, Tex, j'investis dans les gens qui me doivent de l'argent.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0271_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0271', 'turn': 2, 'speaker': 'B', 'context': 'oil investment'},
    {'cat': 'dialogue', 'text': 'Ha ! Je ne te dois rien !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0271_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0271', 'turn': 3, 'speaker': 'A', 'context': 'oil investment'},
    {'cat': 'dialogue', 'text': 'Pas encore, mon ami.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0271_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0271', 'turn': 4, 'speaker': 'B', 'context': 'oil investment'},
    {'cat': 'dialogue', 'text': 'Vous, je vous connais. Vous avez débarqué des caisses de whisky à New York.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0272_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0272', 'turn': 1, 'speaker': 'A', 'context': 'whisky crates'},
    {'cat': 'dialogue', 'text': 'Moi, capitaine ? Des caisses de lait. Pour les orphelins.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0272_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0272', 'turn': 2, 'speaker': 'B', 'context': 'whisky crates'},
    {'cat': 'dialogue', 'text': 'Des orphelins très assoiffés.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0272_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0272', 'turn': 3, 'speaker': 'A', 'context': 'whisky crates'},
    {'cat': 'dialogue', 'text': 'Monsieur, retirez vos gants pour saluer une duchesse.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0273_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0273', 'turn': 1, 'speaker': 'A', 'context': 'gloves duchess'},
    {'cat': 'dialogue', 'text': 'Duchesse, mes gants restent. Mais mon respect, il est total.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0273_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0273', 'turn': 2, 'speaker': 'B', 'context': 'gloves duchess'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Vivienne, à Hollywood, je connais des gens.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0274_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0274', 'turn': 1, 'speaker': 'A', 'context': 'producers'},
    {'cat': 'dialogue', 'text': 'Oh, darling ! Des producteurs ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0274_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0274', 'turn': 2, 'speaker': 'B', 'context': 'producers'},
    {'cat': 'dialogue', 'text': 'Des gens qui convainquent les producteurs.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0274_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0274', 'turn': 3, 'speaker': 'A', 'context': 'producers'},
    {'cat': 'dialogue', 'text': 'Monsieur Tony, vous faites disparaître les problèmes, paraît-il.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0275_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0275', 'turn': 1, 'speaker': 'A', 'context': 'methods'},
    {'cat': 'dialogue', 'text': 'Ça dépend du problème, madame.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0275_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0275', 'turn': 2, 'speaker': 'B', 'context': 'methods'},
    {'cat': 'dialogue', 'text': "Je n'en ai plus. Je voulais seulement comparer nos méthodes.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0275_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0275', 'turn': 3, 'speaker': 'A', 'context': 'methods'},
    {'cat': 'dialogue', 'text': 'Monsieur, vous voulez que je vous débarrasse de vos gants ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0276_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0276', 'turn': 1, 'speaker': 'A', 'context': 'touch gloves'},
    {'cat': 'dialogue', 'text': 'Touche pas aux gants, ma petite. Jamais.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0276_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0276', 'turn': 2, 'speaker': 'B', 'context': 'touch gloves'},
    {'cat': 'dialogue', 'text': 'Tony. Tu te souviens de La Nouvelle-Orléans ?', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0277_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0277', 'turn': 1, 'speaker': 'A', 'context': 'new orleans'},
    {'cat': 'dialogue', 'text': "Je me souviens de tout, Lou. C'est mon métier.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0277_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0277', 'turn': 2, 'speaker': 'B', 'context': 'new orleans'},
    {'cat': 'dialogue', 'text': 'Alors souviens-toi que tu me dois une chanson payée.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0277_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0277', 'turn': 3, 'speaker': 'A', 'context': 'new orleans'},
    {'cat': 'dialogue', 'text': 'Tony les Gants, une interview ? Votre métier exact ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0278_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0278', 'turn': 1, 'speaker': 'A', 'context': 'import export'},
    {'cat': 'dialogue', 'text': "Import-export, ma belle. J'importe des problèmes, j'exporte des solutions.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0278_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0278', 'turn': 2, 'speaker': 'B', 'context': 'import export'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Mei, à Shanghai, vous connaissez la Bande Verte ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0279_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0279', 'turn': 1, 'speaker': 'A', 'context': 'green gang'},
    {'cat': 'dialogue', 'text': 'Je connais beaucoup de couleurs, monsieur Tony. Le vert ne me va pas.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0279_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0279', 'turn': 2, 'speaker': 'B', 'context': 'green gang'},
    {'cat': 'dialogue', 'text': 'Capitaine ! Au Texas, nos tempêtes arrachent les maisons !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0280_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0280', 'turn': 1, 'speaker': 'A', 'context': 'texas storms'},
    {'cat': 'dialogue', 'text': "En mer, monsieur Callahan, elles arrachent les mâts. Et l'orgueil.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0280_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0280', 'turn': 2, 'speaker': 'B', 'context': 'texas storms'},
    {'cat': 'dialogue', 'text': 'Duchesse ! Vous êtes plus jolie que mon puits numéro trois !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0281_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0281', 'turn': 1, 'speaker': 'A', 'context': 'well number three'},
    {'cat': 'dialogue', 'text': "Monsieur, j'ignore ce qu'est un puits, mais je vous interdis de m'y comparer.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0281_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0281', 'turn': 2, 'speaker': 'B', 'context': 'well number three'},
    {'cat': 'dialogue', 'text': 'Oh, monsieur Callahan, vous achèteriez un studio pour moi ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0282_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0282', 'turn': 1, 'speaker': 'A', 'context': 'studio'},
    {'cat': 'dialogue', 'text': "Ha ! Pour vous, ma belle, j'achète Hollywood en entier !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0282_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0282', 'turn': 2, 'speaker': 'B', 'context': 'studio'},
    {'cat': 'dialogue', 'text': "Madame, vous avez l'air bien triste ! Un petit whisky ?", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0283_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0283', 'turn': 1, 'speaker': 'A', 'context': 'whisky'},
    {'cat': 'dialogue', 'text': 'Merci. Mon dernier mari aussi adorait le whisky.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0283_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0283', 'turn': 2, 'speaker': 'B', 'context': 'whisky'},
    {'cat': 'dialogue', 'text': 'Et que lui est-il arrivé ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0283_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0283', 'turn': 3, 'speaker': 'A', 'context': 'whisky'},
    {'cat': 'dialogue', 'text': 'Plus rien. Plus jamais rien.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0283_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0283', 'turn': 4, 'speaker': 'B', 'context': 'whisky'},
    {'cat': 'dialogue', 'text': 'Monsieur, votre chapeau ne passe pas les portes !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0284_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0284', 'turn': 1, 'speaker': 'A', 'context': 'doors'},
    {'cat': 'dialogue', 'text': 'Ha ha ! Au Texas, on agrandit les portes, ma petite !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0284_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0284', 'turn': 2, 'speaker': 'B', 'context': 'doors'},
    {'cat': 'dialogue', 'text': 'Le Texas, hein ? Mon père cueillait le coton, là-bas, honey.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0285_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0285', 'turn': 1, 'speaker': 'A', 'context': 'cotton'},
    {'cat': 'dialogue', 'text': "Ah... Alors je vous dois peut-être bien plus qu'une chanson, madame.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0285_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0285', 'turn': 2, 'speaker': 'B', 'context': 'cotton'},
    {'cat': 'dialogue', 'text': 'Monsieur Callahan, combien de puits de pétrole, exactement ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0286_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0286', 'turn': 1, 'speaker': 'A', 'context': 'four wells'},
    {'cat': 'dialogue', 'text': 'Des centaines !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0286_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0286', 'turn': 2, 'speaker': 'B', 'context': 'four wells'},
    {'cat': 'dialogue', 'text': 'Les registres en mentionnent quatre.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0286_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0286', 'turn': 3, 'speaker': 'A', 'context': 'four wells'},
    {'cat': 'dialogue', 'text': 'Ha ! De très, très grands puits !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0286_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0286', 'turn': 4, 'speaker': 'B', 'context': 'four wells'},
    {'cat': 'dialogue', 'text': 'Mademoiselle ! Vous connaissez le Texas ?', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0287_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0287', 'turn': 1, 'speaker': 'A', 'context': 'stocks'},
    {'cat': 'dialogue', 'text': 'Je connais vos actions, monsieur Callahan. Elles ont baissé hier.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0287_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0287', 'turn': 2, 'speaker': 'B', 'context': 'stocks'},
    {'cat': 'dialogue', 'text': "Capitaine, votre paquebot était d'un inconfort !", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0288_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0288', 'turn': 1, 'speaker': 'A', 'context': 'suite'},
    {'cat': 'dialogue', 'text': 'Vous aviez la plus belle suite, duchesse.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0288_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0288', 'turn': 2, 'speaker': 'B', 'context': 'suite'},
    {'cat': 'dialogue', 'text': 'Justement. Elle tanguait.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0288_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0288', 'turn': 3, 'speaker': 'A', 'context': 'suite'},
    {'cat': 'dialogue', 'text': 'Capitaine, on va faire naufrage ?', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0289_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0289', 'turn': 1, 'speaker': 'A', 'context': 'shipwreck'},
    {'cat': 'dialogue', 'text': "Nous sommes sur une île, mademoiselle. C'est déjà fait.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0289_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0289', 'turn': 2, 'speaker': 'B', 'context': 'shipwreck'},
    {'cat': 'dialogue', 'text': 'Capitaine, la mer rend-elle toujours les corps ?', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0290_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0290', 'turn': 1, 'speaker': 'A', 'context': 'the sea returns'},
    {'cat': 'dialogue', 'text': 'Pas toujours, madame. Pourquoi ?', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0290_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0290', 'turn': 2, 'speaker': 'B', 'context': 'the sea returns'},
    {'cat': 'dialogue', 'text': 'Pour mon premier mari. Il nageait mal.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0290_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0290', 'turn': 3, 'speaker': 'A', 'context': 'the sea returns'},
    {'cat': 'dialogue', 'text': 'Capitaine, vous voulez une tisane ? Pour la tempête ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0291_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0291', 'turn': 1, 'speaker': 'A', 'context': 'herbal tea'},
    {'cat': 'dialogue', 'text': "Un rhum, plutôt, mademoiselle. C'est la tisane des marins.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0291_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0291', 'turn': 2, 'speaker': 'B', 'context': 'herbal tea'},
    {'cat': 'dialogue', 'text': "Capitaine, tu as l'air d'un homme qui a vu beaucoup d'adieux.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0292_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0292', 'turn': 1, 'speaker': 'A', 'context': 'farewells'},
    {'cat': 'dialogue', 'text': 'Sur les quais, madame, on en voit tous les jours. Les chansons les rendent plus légers.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0292_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0292', 'turn': 2, 'speaker': 'B', 'context': 'farewells'},
    {'cat': 'dialogue', 'text': "Capitaine, le phare s'est éteint à quelle heure, exactement ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0293_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0293', 'turn': 1, 'speaker': 'A', 'context': 'logbook'},
    {'cat': 'dialogue', 'text': "Vingt-trois heures dix. Je l'ai noté. Vieille habitude du livre de bord.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0293_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0293', 'turn': 2, 'speaker': 'B', 'context': 'logbook'},
    {'cat': 'dialogue', 'text': "Moi aussi, j'ai un livre de bord.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0293_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0293', 'turn': 3, 'speaker': 'A', 'context': 'logbook'},
    {'cat': 'dialogue', 'text': "Capitaine, avez-vous navigué jusqu'à Shanghai ?", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0294_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0294', 'turn': 1, 'speaker': 'A', 'context': 'bad tea'},
    {'cat': 'dialogue', 'text': "Douze fois, mademoiselle. Et je n'y ai jamais bu un thé aussi mauvais qu'ici.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0294_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0294', 'turn': 2, 'speaker': 'B', 'context': 'bad tea'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, on voit vos épaules.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0295_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0295', 'turn': 1, 'speaker': 'A', 'context': 'shoulders'},
    {'cat': 'dialogue', 'text': "Oh, darling, c'est le principe de la robe !", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0295_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0295', 'turn': 2, 'speaker': 'B', 'context': 'shoulders'},
    {'cat': 'dialogue', 'text': 'De mon temps, le principe était de les cacher.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0295_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0295', 'turn': 3, 'speaker': 'A', 'context': 'shoulders'},
    {'cat': 'dialogue', 'text': 'Encore en noir, Ophélie ?', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0296_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0296', 'turn': 1, 'speaker': 'A', 'context': 'next one'},
    {'cat': 'dialogue', 'text': 'Toujours, duchesse. On ne sait jamais qui sera le prochain.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0296_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0296', 'turn': 2, 'speaker': 'B', 'context': 'next one'},
    {'cat': 'dialogue', 'text': "Pas moi, j'espère.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0296_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0296', 'turn': 3, 'speaker': 'A', 'context': 'next one'},
    {'cat': 'dialogue', 'text': "Ce n'est pas moi qui décide.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0296_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0296', 'turn': 4, 'speaker': 'B', 'context': 'next one'},
    {'cat': 'dialogue', 'text': 'Petite ! Mon porto. Et ne courez pas, voyons.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0297_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0297', 'turn': 1, 'speaker': 'A', 'context': 'port'},
    {'cat': 'dialogue', 'text': 'Oui, madame la duchesse ! Je marche vite, alors !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0297_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0297', 'turn': 2, 'speaker': 'B', 'context': 'port'},
    {'cat': 'dialogue', 'text': 'Madame, votre chanson était... inhabituelle.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0298_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0298', 'turn': 1, 'speaker': 'A', 'context': 'blues for her'},
    {'cat': 'dialogue', 'text': "Mmm, merci, duchesse. C'est du blues. Ça parle de gens qui ont mal.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0298_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0298', 'turn': 2, 'speaker': 'B', 'context': 'blues for her'},
    {'cat': 'dialogue', 'text': 'Alors elle parlait de moi.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0298_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0298', 'turn': 3, 'speaker': 'A', 'context': 'blues for her'},
    {'cat': 'dialogue', 'text': 'Duchesse, votre âge, pour mon article ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0299_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0299', 'turn': 1, 'speaker': 'A', 'context': 'eternal'},
    {'cat': 'dialogue', 'text': 'Voyons ! Écrivez : éternelle.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0299_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0299', 'turn': 2, 'speaker': 'B', 'context': 'eternal'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, vous parlez un français remarquable.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0300_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0300', 'turn': 1, 'speaker': 'A', 'context': 'your era'},
    {'cat': 'dialogue', 'text': "Merci, duchesse. Je l'ai appris dans des livres de votre époque.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0300_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0300', 'turn': 2, 'speaker': 'B', 'context': 'your era'},
    {'cat': 'dialogue', 'text': "Ah ! Enfin quelqu'un de bien élevé.", 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0300_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0300', 'turn': 3, 'speaker': 'A', 'context': 'your era'},
    {'cat': 'dialogue', 'text': 'Oh, Ophélie darling, le noir vous va si bien !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0301_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0301', 'turn': 1, 'speaker': 'A', 'context': 'black suits you'},
    {'cat': 'dialogue', 'text': 'Merci. Il vous irait aussi. Un jour.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0301_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0301', 'turn': 2, 'speaker': 'B', 'context': 'black suits you'},
    {'cat': 'dialogue', 'text': "Oh ! C'est gentil ! Je crois.", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0301_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0301', 'turn': 3, 'speaker': 'A', 'context': 'black suits you'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Vivienne, je peux avoir un autographe ? Pour ma mère ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0302_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0302', 'turn': 1, 'speaker': 'A', 'context': 'autograph mom'},
    {'cat': 'dialogue', 'text': "Oh, of course, darling ! Elle s'appelle comment ?", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0302_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0302', 'turn': 2, 'speaker': 'B', 'context': 'autograph mom'},
    {'cat': 'dialogue', 'text': 'Maman.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0302_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0302', 'turn': 3, 'speaker': 'A', 'context': 'autograph mom'},
    {'cat': 'dialogue', 'text': 'Lou, darling, apprenez-moi à chanter comme vous !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0303_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0303', 'turn': 1, 'speaker': 'A', 'context': 'broken heart'},
    {'cat': 'dialogue', 'text': "Mmm, d'abord, honey, il faut avoir le cœur brisé.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0303_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0303', 'turn': 2, 'speaker': 'B', 'context': 'broken heart'},
    {'cat': 'dialogue', 'text': 'Oh ! Cette semaine, ça va être compliqué.', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0303_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0303', 'turn': 3, 'speaker': 'A', 'context': 'broken heart'},
    {'cat': 'dialogue', 'text': 'Vivienne, votre vrai nom, pour mon journal ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0304_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0304', 'turn': 1, 'speaker': 'A', 'context': 'doris'},
    {'cat': 'dialogue', 'text': "Oh, darling, c'est Doris. Ne l'écrivez pas !", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0304_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0304', 'turn': 2, 'speaker': 'B', 'context': 'doris'},
    {'cat': 'dialogue', 'text': 'Trop tard.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0304_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0304', 'turn': 3, 'speaker': 'A', 'context': 'doris'},
    {'cat': 'dialogue', 'text': "Mei, darling, votre robe ! C'est de la soie ?", 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0305_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0305', 'turn': 1, 'speaker': 'A', 'context': 'silk'},
    {'cat': 'dialogue', 'text': 'Oui. Brodée à la main pendant trois mois.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0305_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0305', 'turn': 2, 'speaker': 'B', 'context': 'silk'},
    {'cat': 'dialogue', 'text': 'Trois mois ? Moi, je change de robe trois fois par soir !', 'voice': 'char_vivienne_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0305_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0305', 'turn': 3, 'speaker': 'A', 'context': 'silk'},
    {'cat': 'dialogue', 'text': "Madame Ophélie, votre thé. Sans sucre, comme vous l'aimez.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0306_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0306', 'turn': 1, 'speaker': 'A', 'context': 'tasted'},
    {'cat': 'dialogue', 'text': "Merci, Rosalie. Vous l'avez goûté ?", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0306_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0306', 'turn': 2, 'speaker': 'B', 'context': 'tasted'},
    {'cat': 'dialogue', 'text': 'Euh... non, madame. Pourquoi ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0306_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0306', 'turn': 3, 'speaker': 'A', 'context': 'tasted'},
    {'cat': 'dialogue', 'text': 'Pour rien.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0306_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0306', 'turn': 4, 'speaker': 'B', 'context': 'tasted'},
    {'cat': 'dialogue', 'text': 'Mmm, toi, honey, tu caches un chagrin derrière ce voile.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0307_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0307', 'turn': 1, 'speaker': 'A', 'context': 'three sorrows'},
    {'cat': 'dialogue', 'text': 'Trois chagrins, madame. Je les cache très bien.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0307_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0307', 'turn': 2, 'speaker': 'B', 'context': 'three sorrows'},
    {'cat': 'dialogue', 'text': 'Pas à moi.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0307_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0307', 'turn': 3, 'speaker': 'A', 'context': 'three sorrows'},
    {'cat': 'dialogue', 'text': "Madame, vos trois maris sont morts d'accident. Curieux, non ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0308_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0308', 'turn': 1, 'speaker': 'A', 'context': 'accidents'},
    {'cat': 'dialogue', 'text': 'Très curieux. Vous êtes mariée, mademoiselle ?', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0308_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0308', 'turn': 2, 'speaker': 'B', 'context': 'accidents'},
    {'cat': 'dialogue', 'text': 'Pas encore.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0308_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0308', 'turn': 3, 'speaker': 'A', 'context': 'accidents'},
    {'cat': 'dialogue', 'text': 'Restez prudente.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0308_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0308', 'turn': 4, 'speaker': 'B', 'context': 'accidents'},
    {'cat': 'dialogue', 'text': "Votre voile cache vos yeux, madame. C'est pratique.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0309_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0309', 'turn': 1, 'speaker': 'A', 'context': 'veils'},
    {'cat': 'dialogue', 'text': "Votre politesse cache les vôtres, mademoiselle. C'est plus élégant.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0309_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0309', 'turn': 2, 'speaker': 'B', 'context': 'veils'},
    {'cat': 'dialogue', 'text': 'Madame Lou, vous voulez une tisane pour votre voix ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0310_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0310', 'turn': 1, 'speaker': 'A', 'context': 'a drop of bourbon'},
    {'cat': 'dialogue', 'text': 'Mmm, merci, ma chérie. Mets-y une goutte de bourbon.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0310_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0310', 'turn': 2, 'speaker': 'B', 'context': 'a drop of bourbon'},
    {'cat': 'dialogue', 'text': 'Une goutte, ou une bonne goutte ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0310_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0310', 'turn': 3, 'speaker': 'A', 'context': 'a drop of bourbon'},
    {'cat': 'dialogue', 'text': 'Tu me plais, toi.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0310_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0310', 'turn': 4, 'speaker': 'B', 'context': 'a drop of bourbon'},
    {'cat': 'dialogue', 'text': "Rosalie, qu'avez-vous vu dans le bureau d'Ashcombe ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0311_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0311', 'turn': 1, 'speaker': 'A', 'context': 'the will'},
    {'cat': 'dialogue', 'text': 'Un tas de papiers, mademoiselle, et un testament tout neuf.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0311_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0311', 'turn': 2, 'speaker': 'B', 'context': 'the will'},
    {'cat': 'dialogue', 'text': "Et le nom de l'héritier ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0311_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0311', 'turn': 3, 'speaker': 'A', 'context': 'the will'},
    {'cat': 'dialogue', 'text': "Je sais pas lire l'écriture penchée.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0311_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0311', 'turn': 4, 'speaker': 'B', 'context': 'the will'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Mei, vos épingles en jade, elles sont vraies ?', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0312_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0312', 'turn': 1, 'speaker': 'A', 'context': 'jade pins'},
    {'cat': 'dialogue', 'text': 'Aussi vraies que votre curiosité, Rosalie.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0312_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0312', 'turn': 2, 'speaker': 'B', 'context': 'jade pins'},
    {'cat': 'dialogue', 'text': 'Lou, que pensez-vous des gens de ce bal ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0313_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0313', 'turn': 1, 'speaker': 'A', 'context': 'quote'},
    {'cat': 'dialogue', 'text': 'Mmm, honey, ils rient fort pour ne pas entendre leur cœur.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0313_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0313', 'turn': 2, 'speaker': 'B', 'context': 'quote'},
    {'cat': 'dialogue', 'text': 'Je peux vous citer ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0313_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0313', 'turn': 3, 'speaker': 'A', 'context': 'quote'},
    {'cat': 'dialogue', 'text': 'Cite-moi en chantant.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0313_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0313', 'turn': 4, 'speaker': 'B', 'context': 'quote'},
    {'cat': 'dialogue', 'text': 'Votre voix est très belle, madame Lou.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0314_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0314', 'turn': 1, 'speaker': 'A', 'context': 'dare'},
    {'cat': 'dialogue', 'text': 'Merci, ma chérie. La tienne aussi, quand tu oses dire ce que tu penses.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0314_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0314', 'turn': 2, 'speaker': 'B', 'context': 'dare'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Mei, que faites-vous vraiment en France ?', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0315_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0315', 'turn': 1, 'speaker': 'A', 'context': 'really'},
    {'cat': 'dialogue', 'text': 'Je visite. Et vous, que faites-vous vraiment à ce bal ?', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0315_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0315', 'turn': 2, 'speaker': 'B', 'context': 'really'},
    {'cat': 'dialogue', 'text': 'Touchée.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0315_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0315', 'turn': 3, 'speaker': 'A', 'context': 'really'},
]
